    /// <summary>
    /// Which channel category owns each exception, where the library filters one.
    /// </summary>
    /// <remarks>
    /// The library keeps one exception buffer per channel and skips a channel that
    /// does not own the exception's category, so this decides which host hears
    /// what. An exception in no category reaches every open channel.
    /// </remarks>
    public static FrozenDictionary<byte, SasCategory> ExceptionCategories { get; } =
        new Dictionary<byte, SasCategory>
        {
            [0x3F] = SasCategory.Validation,
            [0x56] = SasCategory.Progressive,
            [0x57] = SasCategory.Validation,
            [0x66] = SasCategory.Aft,
            [0x67] = SasCategory.Validation,
            [0x68] = SasCategory.Validation,
            [0x69] = SasCategory.Aft,
            [0x6A] = SasCategory.Aft,
            [0x6B] = SasCategory.Aft,
            [0x6C] = SasCategory.Aft,
            [0x6D] = SasCategory.Aft,
            [0x6E] = SasCategory.Aft,
            [0x6F] = SasCategory.Aft,
            [0x7C] = SasCategory.LegacyBonus,
            [0x8E] = SasCategory.ComponentAuthentication,
            [0x8F] = SasCategory.ComponentAuthentication,
        }.ToFrozenDictionary();

    /// <summary>
    /// Which enabled-feature bits the library clears when answering on a channel
    /// that does not own the category, by feature byte.
    /// </summary>
    /// <remarks>
    /// The features describe the machine and are configured once, but the poll that
    /// reports them is answered on a channel - so a channel with no validation must
    /// not tell its host the machine redeems tickets.
    /// </remarks>
    public static FrozenDictionary<SasCategory, IReadOnlyList<SasFeatureMask>>
        ChannelFeatureMasks { get; } =
        new Dictionary<SasCategory, IReadOnlyList<SasFeatureMask>>
        {
            [SasCategory.Aft] = [new(0, 0x02), new(1, 0x40)],
            [SasCategory.ComponentAuthentication] = [new(1, 0x10)],
            [SasCategory.LegacyBonus] = [new(0, 0x05)],
            [SasCategory.Progressive] = [new(2, 0x02)],
            [SasCategory.Validation] = [new(0, 0xF0)],
        }.ToFrozenDictionary();

    /// <summary>How many of each the catalogue holds, for a report header.</summary>
    public static (int LongPolls, int Exceptions, int Meters) Counts =>
        (LongPolls.Count, Exceptions.Count, Meters.Count);
}
